window.GOVERNMENT_DATA = {"id":"government","title":"ФКЗ о Премьер-министре и Правительстве","full_title":"ФЕДЕРАЛЬНЫЙ КОНСТИТУЦИОННЫЙ ЗАКОН «О ПРЕМЬЕР-МИНИСТРЕ РО И ПРАВИТЕЛЬСТВЕ РО»","revision":"06.09.2026","source_url":"https://forum.russia.online/threads/federal-nyi-konstitutsionnyi-zakon-o-prem-yer-ministre-ro-i-pravitel-stve-ro.4958/","post_id":"post-16543","preamble":"Настоящий Федеральный конституционный закон определяет статус, порядок избрания, вступления в должность, осуществления и прекращения полномочий Премьер-министра РО, порядок временного исполнения его обязанностей, а также статус, состав, полномочия и порядок деятельности Правительства РО.","signature":"Нормативно-правовой акт подписан Премьер-министром РО 06.09.2026 Марк Брагин ​","type_detected":"A","nodes":[{"type":"chapter","number":"I","title":"ОБЩИЕ ПОЛОЖЕНИЯ​","children":[{"type":"article","number":"1","title":"Предмет регулирования","children":[{"type":"paragraph","number":"1","text":"Настоящий Федеральный конституционный закон регулирует организацию и деятельность Премьер-министра РО и Правительства РО."},{"type":"paragraph","number":"2","text":"Премьер-министр и Правительство осуществляют полномочия только в пределах Конституции РО, федеральных конституционных законов, кодексов и федеральных законов."},{"type":"paragraph","number":"3","text":"Положения настоящего Федерального конституционного закона не могут толковаться как предоставляющие Премьер-министру или Правительству право вмешиваться в осуществление правосудия, расследование конкретного уголовного дела, прокурорский надзор или оперативно-розыскную деятельность иначе как в формах, прямо предусмотренных федеральным законодательством."}]},{"type":"article","number":"2","title":"Основные принципы деятельности","children":[{"type":"paragraph","text":"Деятельность Премьер-министра и Правительства основывается на принципах законности, публичности, ответственности, разграничения компетенции государственных органов, защиты прав и свобод человека и гражданина, коллегиальности деятельности Правительства и недопустимости злоупотребления государственными полномочиями."}]},{"type":"article","number":"3","title":"Правовая основа деятельности","children":[{"type":"paragraph","number":"1","text":"Правовую основу деятельности Премьер-министра и Правительства составляют Конституция РО, настоящий Федеральный конституционный закон, иные федеральные конституционные законы, кодексы и федеральные законы."},{"type":"paragraph","number":"2","text":"Премьер-министр осуществляет полномочия посредством указов, распоряжений и иных предусмотренных законом актов."},{"type":"paragraph","number":"3","text":"Правительство осуществляет полномочия посредством постановлений, распоряжений, решений и иных актов в пределах своей компетенции."},{"type":"paragraph","number":"4","text":"Акт Премьер-министра или Правительства, противоречащий акту большей юридической силы, применению не подлежит."}]}]},{"type":"chapter","number":"II","title":"ПРЕМЬЕР-МИНИСТР РО​","children":[{"type":"article","number":"4","title":"Статус Премьер-министра РО","children":[{"type":"paragraph","number":"1","text":"Премьер-министр РО является главой государства, высшим должностным лицом РО и гарантом Конституции РО, прав и свобод человека и гражданина."},{"type":"paragraph","number":"2","text":"Премьер-министр обеспечивает согласованное функционирование государственных органов и определяет основные направления государственной политики."},{"type":"paragraph","number":"3","text":"Премьер-министр осуществляет общее руководство исполнительной властью, не подменяя Правительство при осуществлении его коллегиальных полномочий."},{"type":"paragraph","number":"4","text":"Премьер-министр не является членом Парламента РО и не участвует в парламентском голосовании."}]},{"type":"article","number":"5","title":"Требования к кандидату на должность Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министром может быть избран гражданин РО, достигший двадцати одного года."},{"type":"paragraph","number":"2","text":"Кандидат на должность Премьер-министра не должен:","children":[{"type":"subparagraph","number":"1","text":"иметь непогашенную судимость за умышленное преступление;"},{"type":"subparagraph","number":"2","text":"быть признанным судом недееспособным;"},{"type":"subparagraph","number":"3","text":"иметь иное прямо установленное федеральным законом ограничение, несовместимое с исполнением полномочий Премьер-министра."}]},{"type":"paragraph","number":"3","text":"Дополнительные требования к регистрации кандидатов могут устанавливаться федеральным законом о выборах, если они не противоречат Конституции и настоящему Федеральному конституционному закону."}]},{"type":"article","number":"6","title":"Избрание Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр избирается гражданами РО на основе всеобщего, равного и прямого избирательного права при тайном голосовании."},{"type":"paragraph","number":"2","text":"Выборы Премьер-министра проводятся в порядке, установленном федеральным законодательством о выборах."},{"type":"paragraph","number":"3","text":"Избранным считается зарегистрированный кандидат, получивший наибольшее количество действительных голосов."},{"type":"paragraph","number":"4","text":"При равенстве наибольшего количества голосов проводится повторное голосование между кандидатами, получившими одинаковый результат, в срок, установленный избирательным законодательством."},{"type":"paragraph","number":"5","text":"Итоги выборов подлежат официальному опубликованию."}]},{"type":"article","number":"7","title":"Срок полномочий Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр избирается сроком на сорок пять календарных дней."},{"type":"paragraph","number":"2","text":"Полномочия действующего Премьер-министра прекращаются с момента принесения присяги вновь избранным Премьер-министром, если они не были прекращены ранее."},{"type":"paragraph","number":"3","text":"Одно и то же лицо может быть избрано Премьер-министром повторно, если иное ограничение прямо не установлено федеральным конституционным законом."}]},{"type":"article","number":"8","title":"Вступление Премьер-министра в должность","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вступает в должность после официального опубликования результатов выборов и принесения присяги."},{"type":"paragraph","number":"2","text":"Присяга Премьер-министра приносится публично перед гражданами РО и, при наличии такой возможности, в присутствии представителей Парламента, Правительства и Верховного Суда."},{"type":"paragraph","number":"3","text":"Текст присяги: «Клянусь при осуществлении полномочий Премьер-министра РО соблюдать и защищать Конституцию РО, права и свободы человека и гражданина, действовать в интересах РО, добросовестно исполнять возложенные на меня полномочия и не использовать государственную власть в личных интересах»."},{"type":"paragraph","number":"4","text":"С момента принесения присяги лицо приобретает все полномочия Премьер-министра."}]},{"type":"article","number":"9","title":"Несовместимость должности Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр не вправе одновременно занимать иной парламентский мандат."},{"type":"paragraph","number":"2","text":"Премьер-министр вправе сохранять партийную принадлежность, однако не вправе использовать государственные полномочия для предоставления политической партии незаконных преимуществ."},{"type":"paragraph","number":"3","text":"Премьер-министр не вправе использовать должность для ведения личной предпринимательской деятельности, распоряжения государственным имуществом в личных целях либо получения незаконной имущественной выгоды."}]}]},{"type":"chapter","number":"III","title":"ПОЛНОМОЧИЯ ПРЕМЬЕР-МИНИСТРА РО​","children":[{"type":"article","number":"10","title":"Общие полномочия Премьер-министра","children":[{"type":"paragraph","text":"Премьер-министр РО:","children":[{"type":"subparagraph","number":"1","text":"определяет основные направления внутренней государственной политики;"},{"type":"subparagraph","number":"2","text":"обеспечивает согласованное функционирование органов исполнительной власти;"},{"type":"subparagraph","number":"3","text":"формирует Правительство РО в порядке, установленном настоящим Федеральным конституционным законом;"},{"type":"subparagraph","number":"4","text":"осуществляет общее руководство подчиненными ему государственными органами;"},{"type":"subparagraph","number":"5","text":"представляет РО во взаимоотношениях с государственными и иными организациями;"},{"type":"subparagraph","number":"6","text":"участвует в законодательном процессе;"},{"type":"subparagraph","number":"7","text":"осуществляет полномочия в сфере обороны и государственной безопасности;"},{"type":"subparagraph","number":"8","text":"осуществляет помилование в порядке, установленном настоящим Федеральным конституционным законом;"},{"type":"subparagraph","number":"9","text":"учреждает государственные награды и меры поощрения в пределах федерального законодательства и государственного бюджета;"},{"type":"subparagraph","number":"10","text":"осуществляет иные полномочия, прямо предусмотренные Конституцией и федеральным законодательством."}]}]},{"type":"article","number":"11","title":"Полномочия Премьер-министра по формированию Правительства","children":[{"type":"paragraph","number":"1","text":"Премьер-министр назначает и освобождает от должности Председателя Правительства РО."},{"type":"paragraph","number":"2","text":"Премьер-министр назначает и освобождает от должности федеральных министров, их заместителей и иных членов Правительства, если иной порядок не установлен федеральным законом."},{"type":"paragraph","number":"3","text":"Премьер-министр утверждает структуру Правительства и распределение сфер ответственности между его членами в пределах, установленных федеральным законодательством."},{"type":"paragraph","number":"4","text":"Премьер-министр вправе поручить Председателю Правительства представить предложения по структуре Правительства и кандидатурам его членов."},{"type":"paragraph","number":"5","text":"Освобождение члена Правительства от должности не освобождает его от ответственности за совершенные им правонарушения."}]},{"type":"article","number":"12","title":"Премьер-министр в законодательном процессе","children":[{"type":"paragraph","number":"1","text":"Премьер-министр обладает правом законодательной инициативы."},{"type":"paragraph","number":"2","text":"Премьер-министр вправе вносить в Парламент проекты федеральных конституционных законов, кодексов, федеральных законов и поправок к ним."},{"type":"paragraph","number":"3","text":"Принятый Парламентом закон рассматривается Премьер-министром в порядке и сроки, установленные Конституцией и Федеральным конституционным законом «О Парламенте РО»."},{"type":"paragraph","number":"4","text":"Премьер-министр вправе подписать закон либо возвратить его в Парламент с мотивированными возражениями."},{"type":"paragraph","number":"5","text":"После преодоления вето в установленном порядке Премьер-министр обязан подписать закон и направить его на официальное опубликование."},{"type":"paragraph","number":"6","text":"Премьер-министр не вправе посредством указа или распоряжения изменять, приостанавливать действие либо отменять федеральный закон."}]},{"type":"article","number":"13","title":"Акты Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр издаёт указы и распоряжения."},{"type":"paragraph","number":"2","text":"Указ Премьер-министра может иметь нормативный либо индивидуальный характер."},{"type":"paragraph","number":"3","text":"Распоряжение Премьер-министра издается преимущественно по организационным, кадровым, координационным и иным индивидуальным вопросам."},{"type":"paragraph","number":"4","text":"Акты Премьер-министра обязательны для исполнения на всей территории РО в пределах компетенции Премьер-министра."},{"type":"paragraph","number":"5","text":"Акт Премьер-министра не может противоречить Конституции, федеральным конституционным законам, кодексам и федеральным законам."},{"type":"paragraph","number":"6","text":"Нормативный акт Премьер-министра подлежит официальному опубликованию. Неопубликованный нормативный акт, затрагивающий права, обязанности или ответственность граждан, применению не подлежит."}]},{"type":"article","number":"14","title":"Кадровые полномочия Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр назначает и освобождает должностных лиц в случаях, прямо предусмотренных Конституцией и федеральным законодательством, в том числе Вице-премьера, Министров и их Заместителей."},{"type":"paragraph","number":"2","text":"Премьер-министр назначает на должность и освобождает от должности Министра юстиции РО, одновременно являющегося Генеральным прокурором РО. Назначение на должность Министра юстиции РО влечет одновременное вступление в должность Генерального прокурора РО, а освобождение от должности Министра юстиции РО — одновременное прекращение полномочий Генерального прокурора РО, если федеральным конституционным законом не установлено иное."},{"type":"paragraph","number":"3","text":"Премьер-министр вправе назначать полномочных представителей и советников по отдельным направлениям государственной политики."},{"type":"paragraph","number":"4","text":"Полномочный представитель или советник не приобретает полномочий государственного органа либо должностного лица, если такие полномочия прямо не предоставлены законом."},{"type":"paragraph","number":"5","text":"Объем полномочий представителя или советника определяется актом Премьер-министра в пределах компетенции Премьер-министра."}]},{"type":"article","number":"15","title":"Премьер-министр и государственные организации","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе получать от органов исполнительной власти и подчиненных ему государственных организаций информацию, необходимую для исполнения его полномочий."},{"type":"paragraph","number":"2","text":"Требование о предоставлении информации должно относиться к компетенции Премьер-министра и не может использоваться для незаконного получения сведений по конкретному судебному, следственному, прокурорскому или оперативному производству."},{"type":"paragraph","number":"3","text":"Премьер-министр вправе требовать от руководителей подчиненных ему органов устранения нарушений закона, недостатков организации работы и исполнения законных актов Премьер-министра и Правительства."}]},{"type":"article","number":"16","title":"Премьер-министр и Федеральная служба безопасности","children":[{"type":"paragraph","number":"1","text":"Федеральная служба безопасности подчиняется Премьер-министру РО и Министру юстиции в пределах компетенции каждого из них."},{"type":"paragraph","number":"2","text":"Премьер-министр определяет общие приоритеты деятельности Федеральной службы безопасности в сфере государственной безопасности."},{"type":"paragraph","number":"3","text":"Указания Премьер-министра не могут содержать требование о фабрикации доказательств, незаконном возбуждении или прекращении конкретного уголовного дела, незаконном проведении оперативного мероприятия либо достижении заранее определенного процессуального результата."}]},{"type":"article","number":"17","title":"Премьер-министр и органы внутренних дел","children":[{"type":"paragraph","number":"1","text":"Органы Министерства внутренних дел подчиняются Премьер-министру РО и руководству системы Министерства внутренних дел в установленной законом иерархии."},{"type":"paragraph","number":"2","text":"Премьер-министр вправе определять общие приоритеты государственной политики в сфере общественной безопасности и охраны правопорядка."},{"type":"paragraph","number":"3","text":"Оперативные, административные и процессуальные действия органов внутренних дел осуществляются на основании закона, а не исключительно на основании политического поручения Премьер-министра."}]},{"type":"article","number":"18","title":"Премьер-министр и Вооружённые Силы","children":[{"type":"paragraph","number":"1","text":"Премьер-министр является Верховным Главнокомандующим Вооружёнными Силами РО."},{"type":"paragraph","number":"2","text":"Вооруженные Силы подчиняются Премьер-министру, Министерству внутренних дел и военному командованию в установленной федеральным законодательством иерархии."},{"type":"paragraph","number":"3","text":"Премьер-министр вправе определять основные задачи Вооруженных Сил, утверждать общие направления военной политики и отдавать законные приказы в пределах своей компетенции."},{"type":"paragraph","number":"4","text":"Привлечение Вооруженных Сил к мероприятиям внутренней безопасности допускается только в случаях и порядке, предусмотренных Конституцией, федеральным законодательством или актом о введении особого правового режима."},{"type":"paragraph","number":"5","text":"Приказы Премьер-министра не освобождают военнослужащих от обязанности не исполнять заведомо незаконный приказ в случаях, предусмотренных законом."}]},{"type":"article","number":"19","title":"Полномочия Премьер-министра в особых условиях","children":[{"type":"paragraph","number":"1","text":"Премьер-министр действует при чрезвычайном или военном положении в пределах полномочий, установленных Конституцией и федеральным конституционным законом об особых правовых режимах."},{"type":"paragraph","number":"2","text":"Введение особого правового режима не предоставляет Премьер-министру права отменять Конституцию, прекращать деятельность судов или лишать граждан судебной защиты."},{"type":"paragraph","number":"3","text":"В особых условиях Премьер-министр вправе осуществлять координацию исполнительных и силовых государственных организаций в пределах акта о введении соответствующего режима."}]},{"type":"article","number":"20","title":"Помилование","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе осуществлять помилование лица, в отношении которого вступил в силу обвинительный судебный акт или лицо имеет судимость."},{"type":"paragraph","number":"2","text":"Помилование может выражаться в полном или частичном освобождении от дальнейшего отбывания наказания, сокращении наказания либо замене его более мягкой мерой, если это допускается уголовным законодательством."},{"type":"paragraph","number":"3","text":"Помилование не отменяет факт признания лица виновным и не заменяет судебную процедуру пересмотра незаконного приговора."},{"type":"paragraph","number":"4","text":"Акт о помиловании носит индивидуальный характер и подлежит официальному опубликованию, за исключением сведений, составляющих охраняемую законом тайну."},{"type":"paragraph","number":"5","text":"Премьер-министр не вправе посредством помилования отменить административную, дисциплинарную или гражданско-правовую обязанность, если иное прямо не предусмотрено федеральным законом."}]},{"type":"article","number":"21","title":"Государственные награды и поощрения","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе учреждать государственные награды, почетные звания и иные меры государственного поощрения."},{"type":"paragraph","number":"2","text":"Денежные выплаты и материальные меры поощрения допускаются только в пределах государственного бюджета и установленного финансового порядка."},{"type":"paragraph","number":"3","text":"Награждение не может использоваться как форма оплаты незаконной услуги, подкупа или вознаграждения за совершение противоправного действия."}]},{"type":"article","number":"22","title":"Недопустимость вмешательства Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр не вправе требовать вынесения конкретного судебного решения."},{"type":"paragraph","number":"2","text":"Премьер-министр не вправе требовать возбуждения, прекращения либо направления конкретного уголовного дела при отсутствии предусмотренных законом оснований."},{"type":"paragraph","number":"3","text":"Премьер-министр не вправе требовать фабрикации, сокрытия или уничтожения доказательств."},{"type":"paragraph","number":"4","text":"Премьер-министр не вправе использовать кадровые, финансовые или контрольные полномочия как средство давления на суд, прокуратуру или Следственный комитет по конкретному производству."},{"type":"paragraph","number":"5","text":"Законная межведомственная координация, обеспечение ресурсами, запрос статистической информации и определение общих направлений государственной политики вмешательством не являются."}]},{"type":"article","number":"23","title":"Делегирование полномочий Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе поручать Вице Премьер Министру, федеральным министрам, полномочным представителям и иным подчиненным должностным лицам выполнение отдельных организационных действий."},{"type":"paragraph","number":"2","text":"Не допускается делегирование:","children":[{"type":"subparagraph","number":"1","text":"права подписания или отклонения федерального закона;"},{"type":"subparagraph","number":"2","text":"права осуществления помилования;"},{"type":"subparagraph","number":"3","text":"полномочий Верховного Главнокомандующего, если иное прямо не установлено законом для временного исполнения обязанностей Премьер-министра;"},{"type":"subparagraph","number":"4","text":"полномочий по назначению и освобождению Вице Премьер-министра;"},{"type":"subparagraph","number":"5","text":"иных полномочий, которые Конституцией или федеральным законом предоставлены исключительно Премьер-министру."}]},{"type":"paragraph","number":"3","text":"Делегирование полномочия не освобождает Премьер-министра от политической и правовой ответственности за законность соответствующего решения."}]}]},{"type":"chapter","number":"IV","title":"ГАРАНТИИ, ПРЕКРАЩЕНИЕ ПОЛНОМОЧИЙ И ВРЕМЕННОЕ ИСПОЛНЕНИЕ ОБЯЗАННОСТЕЙ ПРЕМЬЕР-МИНИСТРА​","children":[{"type":"article","number":"24","title":"Неприкосновенность Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр обладает процессуальной неприкосновенностью на период осуществления полномочий."},{"type":"paragraph","number":"2","text":"Неприкосновенность не является освобождением Премьер-министра от уголовной, административной, гражданской или иной установленной законом ответственности."},{"type":"paragraph","number":"3","text":"В отношении Премьер-министра допускается сбор и фиксация доказательств в предусмотренном законом порядке, если такие действия не связаны с незаконным принудительным ограничением его полномочий."},{"type":"paragraph","number":"4","text":"Задержание, арест, обыск Премьер-министра либо иная мера, фактически препятствующая осуществлению им полномочий, допускается на основании судебного акта Верховного Суда в рамках предусмотренной законом процедуры, за исключением необходимости немедленного пресечения непосредственно совершаемого Премьер-министром тяжкого насильственного преступления."},{"type":"paragraph","number":"5","text":"О применении к Премьер-министру меры процессуального принуждения безотлагательно уведомляются Председатель Государственной Думы и Председатель Верховного Суда."},{"type":"paragraph","number":"6","text":"После прекращения полномочий Премьер-министр пользуется общими процессуальными гарантиями, если федеральным законом прямо не установлено иное."}]},{"type":"article","number":"25","title":"Основания прекращения полномочий Премьер-министра","children":[{"type":"paragraph","text":"Полномочия Премьер-министра прекращаются:","children":[{"type":"subparagraph","number":"1","text":"с истечением срока полномочий и принесением присяги вновь избранным Премьер-министром;"},{"type":"subparagraph","number":"2","text":"в результате добровольной отставки;"},{"type":"subparagraph","number":"3","text":"в случае вступления в силу решения об отрешении от должности;"},{"type":"subparagraph","number":"4","text":"в случае смерти;"},{"type":"subparagraph","number":"5","text":"в случае вступления в силу судебного решения о стойкой невозможности исполнять полномочия;"},{"type":"subparagraph","number":"6","text":"в иных случаях, прямо установленных Конституцией или федеральным конституционным законом."}]}]},{"type":"article","number":"26","title":"Добровольная отставка Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе в любое время подать в отставку."},{"type":"paragraph","number":"2","text":"Отставка оформляется письменным публичным заявлением либо официальным актом Премьер-министра."},{"type":"paragraph","number":"3","text":"Отставка вступает в силу с момента её официального объявления, если в ней не указан более поздний момент."},{"type":"paragraph","number":"4","text":"После вступления отставки в силу обязанности Премьер-министра переходят к исполняющему обязанности в порядке, установленном статьей 29 настоящего Федерального конституционного закона."}]},{"type":"article","number":"27","title":"Отрешение Премьер-министра от должности","children":[{"type":"paragraph","number":"1","text":"Премьер-министр может быть отрешен от должности за тяжкое нарушение Конституции РО либо совершение преступления."},{"type":"paragraph","number":"2","text":"Предложение об отрешении может быть внесено не менее чем одной третью установленного состава Парламента."},{"type":"paragraph","number":"3","text":"Предложение должно содержать конкретное описание вменяемых Премьер-министру действий и их правовое обоснование."},{"type":"paragraph","number":"4","text":"До окончательного голосования Парламент направляет материалы в Верховный Суд РО для заключения о наличии предусмотренных законом оснований и соблюдении установленной процедуры."},{"type":"paragraph","number":"5","text":"Верховный Суд не решает вопрос о политической целесообразности отрешения и дает заключение исключительно о юридической стороне предъявленных оснований."},{"type":"paragraph","number":"6","text":"При наличии положительного заключения Верховного Суда Премьер-министр считается отрешенным от должности, если за это проголосовало не менее двух третей установленного состава Парламента."},{"type":"paragraph","number":"7","text":"Отрешение от должности не заменяет уголовное судопроизводство и не означает автоматического признания Премьер-министра виновным в преступлении."},{"type":"paragraph","number":"8","text":"С момента принятия решения об отрешении полномочия Премьер-министра прекращаются."}]},{"type":"article","number":"28","title":"Временная невозможность исполнения полномочий","children":[{"type":"paragraph","number":"1","text":"Временной невозможностью исполнения Премьер-министром полномочий признаются длительное отсутствие, тяжелое состояние здоровья, фактическая недоступность либо иное объективное обстоятельство, временно исключающее осуществление полномочий."},{"type":"paragraph","number":"2","text":"Премьер-министр вправе самостоятельно объявить о временной передаче исполнения обязанностей."},{"type":"paragraph","number":"3","text":"При невозможности такого объявления факт временной невозможности исполнения полномочий может быть установлен Верховным Судом по обращению Вице-премьер-министра, Председателя Государственной Думы либо не менее одной трети установленного состава Парламента."},{"type":"paragraph","number":"4","text":"Временная передача полномочий прекращается с момента официального возвращения Премьер-министра к исполнению обязанностей либо прекращения его полномочий."}]},{"type":"article","number":"29","title":"Исполняющий обязанности Премьер-министра","children":[{"type":"paragraph","number":"1","text":"При досрочном прекращении полномочий Премьер-министра либо временной невозможности их исполнения обязанности Премьер-министра осуществляет Вице Премьер-министр РО."},{"type":"paragraph","number":"2","text":"Если Вице Премьер-министр отсутствует либо объективно не может исполнять обязанности Премьер-министра, они переходят к Председателю Государственной Думы РО."},{"type":"paragraph","number":"3","text":"Если оба указанных должностных лица отсутствуют либо не могут исполнять обязанности, временного исполняющего обязанности Премьер-министра определяет Парламент большинством голосов действующего состава из числа членов Правительства."},{"type":"paragraph","number":"4","text":"Исполняющий обязанности Премьер-министра осуществляет полномочия в объеме, необходимом для непрерывности государственной власти."},{"type":"paragraph","number":"5","text":"Исполняющий обязанности Премьер-министра не вправе:","children":[{"type":"subparagraph","number":"1","text":"инициировать изменение Конституции, направленное на расширение собственных полномочий;"},{"type":"subparagraph","number":"2","text":"использовать временное положение для незаконного перераспределения полномочий государственных органов;"},{"type":"subparagraph","number":"3","text":"без объективной необходимости прекращать полномочия всего состава Правительства;"},{"type":"subparagraph","number":"4","text":"издавать акты, явно не связанные с обеспечением нормального функционирования государства и не терпящие отлагательства, если соответствующее решение может быть принято вновь избранным Премьер-министром."}]},{"type":"paragraph","number":"6","text":"При досрочном прекращении полномочий Премьер-министра новые выборы должны быть назначены в максимально короткий срок, установленный федеральным избирательным законодательством."}]},{"type":"article","number":"29.1","title":"Вице Премьер-министр РО обладает всем спектром полномочий премьер-министра РО, однако остается в его непосредственном подчинении.","children":[]}]},{"type":"chapter","number":"V","title":"ПРАВИТЕЛЬСТВО РО​","children":[{"type":"article","number":"30","title":"Статус Правительства РО","children":[{"type":"paragraph","number":"1","text":"Правительство РО является высшим коллегиальным исполнительным органом государственного управления и государственной власти."},{"type":"paragraph","number":"2","text":"Правительство действует на основании Конституции, федерального законодательства и законных актов Премьер-министра."},{"type":"paragraph","number":"3","text":"Правительство самостоятельно осуществляет коллегиальные полномочия в пределах своей компетенции и подотчетно Премьер-министру по вопросам реализации государственной политики."},{"type":"paragraph","number":"4","text":"Правительство не вправе присваивать полномочия Парламента и суда."}]},{"type":"article","number":"31","title":"Состав Правительства","children":[{"type":"paragraph","number":"1","text":"В состав Правительства входят:","children":[{"type":"subparagraph","number":"1","text":"Вице премьер-министр РО;"},{"type":"subparagraph","number":"2","text":"федеральные министры, возглавляющие федеральные министерства, предусмотренные статьей 34.1 настоящего Федерального конституционного закона;"},{"type":"subparagraph","number":"3","text":"заместители федеральных министров в случаях, когда актом Премьер-министра им предоставлен статус члена Правительства;"},{"type":"subparagraph","number":"4","text":"иные должностные лица, прямо включенные в состав Правительства федеральным законом или указом Премьер-министра, изданным в пределах федерального законодательства."}]},{"type":"paragraph","number":"2","text":"Премьер-министр вправе участвовать в заседаниях Правительства и председательствовать на них."},{"type":"paragraph","number":"3","text":"Включение должностного лица в состав Правительства не предоставляет ему полномочий, выходящих за пределы компетенции занимаемой им должности."}]},{"type":"article","number":"32","title":"Вице-Премьер","children":[{"type":"paragraph","number":"1","text":"Вице-премьер организует текущую деятельность Правительства и обеспечивает исполнение его решений."},{"type":"paragraph","number":"2","text":"Вице-премьер:","children":[{"type":"subparagraph","number":"1","text":"созывает и ведет заседания Правительства, если на них не председательствует Премьер-министр;"},{"type":"subparagraph","number":"2","text":"формирует проект повестки;"},{"type":"subparagraph","number":"3","text":"координирует деятельность членов Правительства;"},{"type":"subparagraph","number":"4","text":"представляет Премьер-министру предложения по структуре Правительства и распределению обязанностей;"},{"type":"subparagraph","number":"5","text":"подписывает постановления и распоряжения Правительства;"},{"type":"subparagraph","number":"6","text":"представляет Правительство во взаимоотношениях с иными государственными органами;"},{"type":"subparagraph","number":"7","text":"осуществляет иные полномочия, предусмотренные федеральным законодательством."}]},{"type":"paragraph","number":"3","text":"Вице-премьер не вправе единолично отменять законные полномочия федерального министра либо независимого государственного органа, если такое право не предоставлено законом."},{"type":"paragraph","number":"4","text":"Вице Премьер-министр РО обладает всем спектром полномочий премьер-министра РО, однако остается в его непосредственном подчинении. Исключение: Введение военного положения."}]},{"type":"article","number":"33","title":"Федеральные министры","children":[{"type":"paragraph","number":"1","text":"Федеральный министр возглавляет соответствующее министерство и несет ответственность за организацию его деятельности."},{"type":"paragraph","number":"2","text":"Министр действует в пределах компетенции министерства, установленной федеральным законодательством и законными актами Премьер-министра и Правительства."},{"type":"paragraph","number":"3","text":"Министр вправе издавать приказы и иные ведомственные акты."},{"type":"paragraph","number":"4","text":"Ведомственный акт не может изменять федеральный закон, устанавливать новый состав правонарушения, расширять компетенцию министерства либо вводить для граждан обязанности, не предусмотренные актом большей юридической силы."},{"type":"paragraph","number":"5","text":"Министр вправе делегировать отдельные полномочия заместителю, если законом не установлено, что соответствующее полномочие осуществляется лично министром."}]},{"type":"article","number":"34","title":"Система федеральных министерств","children":[{"type":"paragraph","number":"1","text":"В РО действуют следующие федеральные министерства:","children":[{"type":"subparagraph","number":"1","text":"Министерство юстиции РО;"},{"type":"subparagraph","number":"2","text":"Министерство внутренних дел РО;"},{"type":"subparagraph","number":"3","text":"Министерство здравоохранения РО;"},{"type":"subparagraph","number":"4","text":"Министерство культуры РО;"},{"type":"subparagraph","number":"5","text":"Министр финансов РО, он же Государственный казначей."}]},{"type":"paragraph","number":"2","text":"Каждое федеральное министерство возглавляется соответствующим федеральным министром, входящим в состав Правительства РО."},{"type":"paragraph","number":"3","text":"Министр юстиции РО одновременно является Генеральным прокурором РО. При осуществлении прокурорских полномочий он действует в качестве Генерального прокурора РО на основании Конституции РО, Федерального закона «О прокуратуре РО» и иного федерального законодательства. Совмещение должностей не означает слияния Министерства юстиции РО и прокуратуры РО и не предоставляет Правительству права вмешиваться в конкретную прокурорскую проверку, определять содержание акта прокурорского реагирования или отменять процессуальное решение прокурора вне установленной законом процедуры."},{"type":"paragraph","number":"4","text":"Министерство юстиции РО осуществляет государственную политику и государственное управление в сфере юстиции, правового обеспечения деятельности исполнительной власти, организации государственной юридической деятельности и иных вопросов, отнесенных федеральным законодательством к его компетенции. В случаях, прямо предусмотренных федеральным законом, Министр юстиции осуществляет общее организационное руководство Федеральной службой безопасности РО без вмешательства в конкретное оперативное или следственное производство."},{"type":"paragraph","number":"5","text":"Министерство внутренних дел РО осуществляет государственную политику и общее организационное руководство в сфере внутренних дел, охраны общественного порядка, обороны, военного строительства, а также деятельности системы МВД России, ГИБДД и Вооруженных Сил РО в пределах федерального законодательства. х руководителями в порядке, установленном профильными федеральными законами."},{"type":"paragraph","number":"6","text":"Непосредственное оперативное руководство соответствующими службами (органами внутренних дел, подразделениями ГИБДД и воинскими формированиями) осуществляется их прямыми руководителями в порядке, установленном профильными федеральными законами. В сфере обороны и военного строительства Министр внутренних дел РО реализует полномочия, делегированные ему Премьер-министром РО как Верховным Главнокомандующим, в пределах установленной законом военной цепи командования."},{"type":"paragraph","number":"7","text":"Министерство здравоохранения РО осуществляет государственную политику и государственное управление в сфере охраны здоровья, деятельности государственных медицинских организаций, экстренной медицинской помощи и иных вопросов здравоохранения."},{"type":"paragraph","number":"8","text":"Министерство культуры РО осуществляет государственную политику и государственное управление в сфере культуры, сохранения культурного наследия, деятельности государственных учреждений культуры и проведения государственных культурных мероприятий."},{"type":"paragraph","number":"9","text":"Государственное казначейство РО осуществляет контроль за финансовыми операциями, происходящими с казны государственных организаций, а также планированием и распределения бюджета."},{"type":"paragraph","number":"9","text":"Конкретные полномочия, внутренняя организация и порядок деятельности федеральных министерств определяются настоящим Федеральным конституционным законом, иными федеральными законами и принятыми на их основании актами Премьер-министра и Правительства РО."},{"type":"paragraph","number":"10","text":"Образование нового федерального министерства, упразднение либо изменение установленного настоящей статьей перечня федеральных министерств допускается только путем внесения изменений в настоящий Федеральный конституционный закон."}]},{"type":"article","number":"35","title":"Прекращение полномочий Правительства и его членов","children":[{"type":"paragraph","number":"1","text":"Член Правительства прекращает полномочия в случае освобождения от должности Премьер-министром, добровольной отставки, прекращения полномочий по иному предусмотренному законом основанию либо смерти."},{"type":"paragraph","number":"2","text":"Прекращение полномочий Премьер-министра само по себе не прекращает полномочия всего Правительства."},{"type":"paragraph","number":"3","text":"Вновь избранный Премьер-министр вправе сформировать новый состав Правительства либо сохранить полномочия действующих членов Правительства."},{"type":"paragraph","number":"4","text":"До назначения преемника освобожденный член Правительства может продолжать исполнение обязанностей в статусе временно исполняющего обязанности, если это прямо определено Премьер-министром и не противоречит закону."}]}]},{"type":"chapter","number":"VI","title":"ПОЛНОМОЧИЯ ПРАВИТЕЛЬСТВА РО​","children":[{"type":"article","number":"36","title":"Общие полномочия Правительства","children":[{"type":"paragraph","text":"Правительство РО:","children":[{"type":"subparagraph","number":"1","text":"обеспечивает исполнение Конституции, федеральных законов и законных актов Премьер-министра;"},{"type":"subparagraph","number":"2","text":"реализует государственную политику в экономической, социальной, трудовой, административной и иных сферах;"},{"type":"subparagraph","number":"3","text":"обеспечивает функционирование органов исполнительной власти и государственных организаций в пределах своей компетенции;"},{"type":"subparagraph","number":"4","text":"управляет государственным бюджетом и имуществом в установленном законом порядке;"},{"type":"subparagraph","number":"5","text":"организует межведомственное взаимодействие;"},{"type":"subparagraph","number":"6","text":"осуществляет предусмотренный законом организационный и финансовый контроль;"},{"type":"subparagraph","number":"7","text":"реализует право законодательной инициативы;"},{"type":"subparagraph","number":"8","text":"принимает нормативные и индивидуальные акты в пределах своей компетенции;"},{"type":"subparagraph","number":"9","text":"обеспечивает защиту прав граждан в сфере деятельности исполнительной власти;"},{"type":"subparagraph","number":"10","text":"осуществляет финансирование и контроль за финансовыми действиями государственных структур;"},{"type":"subparagraph","number":"11","text":"осуществляет иные полномочия, предусмотренные федеральным законодательством."}]}]},{"type":"article","number":"37","title":"Полномочия в сфере экономики и государственного имущества","children":[{"type":"paragraph","number":"1","text":"Правительство осуществляет государственную экономическую политику в пределах федерального законодательства."},{"type":"paragraph","number":"2","text":"Правительство управляет государственным имуществом исключительно в публичных интересах."},{"type":"paragraph","number":"3","text":"Правительство вправе передавать государственное имущество государственным организациям, предоставлять его во временное пользование либо распоряжаться им иным законным способом."},{"type":"paragraph","number":"4","text":"Отчуждение, передача или использование государственного имущества в личных целях должностного лица запрещаются."},{"type":"paragraph","number":"5","text":"Условия аренды либо иного возмездного использования государственного имущества оформляются договором или иным предусмотренным законом документом."},{"type":"paragraph","number":"6","text":"Правительство вправе принимать программы развития отдельных отраслей экономики и государственной инфраструктуры."}]},{"type":"article","number":"38","title":"Бюджет и государственные расходы","children":[{"type":"paragraph","number":"1","text":"Правительство организует исполнение государственного бюджета."},{"type":"paragraph","number":"2","text":"Государственные выплаты, финансирование организаций, премирование служащих и иные расходы осуществляются в пределах утвержденного бюджета и установленного финансового порядка."},{"type":"paragraph","number":"3","text":"Правительство не вправе использовать бюджетные средства для личного обогащения, подкупа, политического давления либо финансирования заведомо незаконной деятельности."},{"type":"paragraph","number":"4","text":"Правительство вправе устанавливать порядок предоставления государственных выплат и премий, если размер, основания и пределы таких выплат соответствуют федеральному законодательству."},{"type":"paragraph","number":"5","text":"По законному запросу Парламента, суда или иного уполномоченного органа Правительство предоставляет информацию об исполнении бюджета с учетом режима охраняемой законом тайны."}]},{"type":"article","number":"39","title":"Полномочия в социальной, трудовой и медицинской сферах","children":[{"type":"paragraph","number":"1","text":"Правительство обеспечивает проведение единой государственной социальной политики."},{"type":"paragraph","number":"2","text":"Правительство принимает меры по реализации трудовых прав граждан, развитию системы государственной службы и обеспечению законных условий труда."},{"type":"paragraph","number":"3","text":"Правительство обеспечивает организационные условия для деятельности государственных медицинских организаций и оказания экстренной медицинской помощи."},{"type":"paragraph","number":"4","text":"Государственная социальная политика не может использоваться для установления обязательной государственной идеологии или дискриминации граждан по основаниям, запрещенным Конституцией."},{"type":"paragraph","number":"5","text":"Правительство вправе утверждать социальные программы и меры поддержки в пределах бюджета и закона."}]},{"type":"article","number":"40","title":"Полномочия в сфере законности и общественной безопасности","children":[{"type":"paragraph","number":"1","text":"Правительство участвует в разработке и реализации государственной политики в сфере общественной и государственной безопасности."},{"type":"paragraph","number":"2","text":"Правительство обеспечивает организационное и материально-техническое взаимодействие исполнительных и силовых государственных организаций."},{"type":"paragraph","number":"3","text":"Правительство не вправе давать следователю, прокурору или судье указание о результате конкретного производства."},{"type":"paragraph","number":"4","text":"Решения Правительства в сфере безопасности должны соответствовать компетенции соответствующих силовых органов и не могут подменять предусмотренные процессуальным законодательством основания задержания, обыска, ареста, розыска или применения силы."}]},{"type":"article","number":"41","title":"Законодательная инициатива Правительства","children":[{"type":"paragraph","number":"1","text":"Правительство вправе разрабатывать и вносить в Парламент проекты федеральных конституционных законов, кодексов, федеральных законов и поправок к ним."},{"type":"paragraph","number":"2","text":"Законодательная инициатива Правительства должна быть мотивированной и соответствовать Конституции."},{"type":"paragraph","number":"3","text":"Правительство вправе поручать федеральным министерствам подготовку проектов нормативных правовых актов в пределах их компетенции."},{"type":"paragraph","number":"4","text":"Правительство не вправе самостоятельно изменять кодекс или федеральный закон посредством постановления, распоряжения, положения, приказа либо иного подзаконного акта."}]},{"type":"article","number":"42","title":"Организационный контроль государственных организаций","children":[{"type":"paragraph","number":"1","text":"Правительство вправе осуществлять организационный, финансовый и служебный контроль органов исполнительной власти и иных подчиненных ему государственных организаций."},{"type":"paragraph","number":"2","text":"Контроль может включать проверку соблюдения законодательства, кадровой дисциплины, исполнения бюджета, внутреннего документооборота, исполнения актов Премьер-министра и Правительства и состояния материально-технического обеспечения."},{"type":"paragraph","number":"3","text":"Контроль не может использоваться для вмешательства в конкретное судебное дело, прокурорскую проверку, уголовное дело или оперативное мероприятие."},{"type":"paragraph","number":"4","text":"Суд и Следственный комитет не подлежат административному контролю Правительства. Прокуратура РО организационно находится в структуре Правительства РО, однако организационное, финансовое и материально-техническое обеспечение прокуратуры не предоставляет Правительству права вмешиваться в конкретную прокурорскую проверку, предопределять содержание акта прокурорского реагирования либо отменять процессуальное решение прокурора вне предусмотренной законом процедуры."},{"type":"paragraph","number":"5","text":"Порядок, сроки и периодичность проверок могут дополнительно определяться федеральным законом или постановлением Правительства, если такое постановление не ограничивает установленные законом гарантии самостоятельности государственных органов."}]},{"type":"article","number":"43","title":"Внутренние акты государственных организаций","children":[{"type":"paragraph","number":"1","text":"Правительство вправе устанавливать общий порядок утверждения регламентов, инструкций, положений об отделах и иных внутренних актов исполнительных государственных организаций."},{"type":"paragraph","number":"2","text":"Внутренний акт подлежит отмене или приведению в соответствие с законом, если он:","children":[{"type":"subparagraph","number":"1","text":"противоречит акту большей юридической силы;"},{"type":"subparagraph","number":"2","text":"расширяет компетенцию организации сверх закона;"},{"type":"subparagraph","number":"3","text":"устанавливает для граждан не предусмотренные законом обязанности, запреты или наказания;"},{"type":"subparagraph","number":"4","text":"нарушает установленное разграничение компетенции государственных органов."}]},{"type":"paragraph","number":"3","text":"Правительство не утверждает внутренние акты судов, прокуратуры и Следственного комитета, если федеральным законом прямо не предусмотрено иное."}]},{"type":"article","number":"44","title":"Лицензирование и государственные разрешения","children":[{"type":"paragraph","number":"1","text":"Правительство организует выдачу и учет адвокатских лицензий и иных государственных разрешений, отнесенных федеральным законодательством к компетенции исполнительной власти."},{"type":"paragraph","number":"2","text":"Условия, основания выдачи, приостановления и отзыва лицензии должны быть определены федеральным законом либо принятым на его основании нормативным актом Правительства."},{"type":"paragraph","number":"3","text":"Отказ в выдаче лицензии, её приостановление или отзыв должны быть мотивированы и могут быть обжалованы."},{"type":"paragraph","number":"4","text":"Размер государственной пошлины или иной платы за лицензирование устанавливается в пределах федерального законодательства."}]},{"type":"article","number":"45","title":"Межведомственная координация","children":[{"type":"paragraph","number":"1","text":"Правительство обеспечивает взаимодействие федеральных министерств и подчиненных им государственных организаций."},{"type":"paragraph","number":"2","text":"Для решения межведомственных вопросов Правительство вправе создавать комиссии, рабочие группы и координационные органы."},{"type":"paragraph","number":"3","text":"Создание координационного органа не изменяет установленную законом компетенцию входящих в него государственных органов."},{"type":"paragraph","number":"4","text":"Следственный комитет, прокуратура и суды могут участвовать в межведомственном взаимодействии только в формах, не нарушающих их самостоятельность."}]},{"type":"article","number":"45.1","title":"Рабочие группы при Премьер-министре РО и Правительстве РО","children":[{"type":"paragraph","number":"1","text":"Премьер-министр РО и Вице Премьер-министр РО вправе формировать постоянные или временные рабочие группы по отдельным направлениям государственной политики, государственного управления, межведомственного взаимодействия и иным вопросам, относящимся к их компетенции."},{"type":"paragraph","number":"2","text":"Рабочая группа является совещательным и консультативным органом при Премьер-министре РО либо Правительстве РО. Рабочая группа не является самостоятельным государственным органом, не обладает собственной властной компетенцией и не вправе самостоятельно принимать нормативные или индивидуальные правовые акты, обязательные для граждан, государственных органов или должностных лиц."},{"type":"paragraph","number":"3","text":"В состав рабочей группы могут входить граждане РО, специалисты и эксперты, члены Правительства РО, руководители и заместители руководителей государственных органов и организаций, иные должностные лица и государственные служащие. Включение гражданина в состав рабочей группы само по себе не наделяет его статусом государственного служащего или должностного лица и не предоставляет ему государственных властных полномочий."},{"type":"paragraph","number":"4","text":"Решением Премьер-министра РО или Председателя Правительства РО о формировании рабочей группы определяются ее наименование, предмет ведения, основные задачи, состав либо порядок его формирования, руководитель рабочей группы, порядок деятельности, а при необходимости — срок ее деятельности."},{"type":"paragraph","number":"5","text":"На рассмотрение рабочей группы могут выноситься вопросы, отнесенные к предмету ее ведения, в том числе вопросы анализа правоприменительной и управленческой практики, межведомственного взаимодействия, выработки государственной политики, подготовки и обсуждения предложений, проектов указов и распоряжений Премьер-министра РО, проектов постановлений и распоряжений Правительства РО, проектов федеральных законов, государственных программ и иных организационных или нормативных решений."},{"type":"paragraph","number":"6","text":"По результатам рассмотрения вопросов рабочая группа вправе формировать заключения, рекомендации, предложения, проекты решений и протокольные позиции. Такие документы носят совещательный характер. Юридические последствия возникают только после принятия соответствующего решения уполномоченным государственным органом или должностным лицом в установленной законом форме."},{"type":"paragraph","number":"7","text":"Для выполнения задач рабочей группы ее участники вправе запрашивать и представлять относящиеся к предмету ведения сведения и материалы в пределах компетенции соответствующих государственных органов и с соблюдением законодательства о государственной тайне и иной охраняемой законом информации. Участие в рабочей группе само по себе не является основанием для получения доступа к сведениям ограниченного доступа."},{"type":"paragraph","number":"8","text":"Создание рабочей группы и участие в ней должностных лиц не изменяют установленную федеральным законодательством компетенцию, подчиненность и ответственность государственных органов и должностных лиц. Каждый участник рабочей группы сохраняет полномочия исключительно в пределах занимаемой им должности и закона."},{"type":"paragraph","number":"9","text":"Премьер-министр РО или Вице Премьер-министр РО, сформировавший рабочую группу, вправе изменять ее состав, задачи и порядок деятельности, а также прекратить ее деятельность."}]},{"type":"article","number":"46","title":"Государственные программы и поручения","children":[{"type":"paragraph","number":"1","text":"Правительство вправе утверждать государственные программы и планы мероприятий в пределах своей компетенции."},{"type":"paragraph","number":"2","text":"Поручение Правительства обязательно для подчиненного органа, если оно законно, конкретно и относится к его компетенции."},{"type":"paragraph","number":"3","text":"Подчиненный орган обязан сообщить о невозможности исполнения поручения, если оно противоречит закону или объективно неисполнимо."},{"type":"paragraph","number":"4","text":"Заведомо незаконное поручение исполнению не подлежит в случаях и порядке, установленных федеральным законодательством."}]}]},{"type":"chapter","number":"VII","title":"ОРГАНИЗАЦИЯ ДЕЯТЕЛЬНОСТИ ПРАВИТЕЛЬСТВА​","children":[{"type":"article","number":"47","title":"Заседания Правительства","children":[{"type":"paragraph","number":"1","text":"Заседания Правительства созываются Председателем Правительства по мере необходимости."},{"type":"paragraph","number":"2","text":"Премьер-министр вправе созвать заседание Правительства и председательствовать на нём."},{"type":"paragraph","number":"3","text":"Заседание правомочно при участии более половины действующего состава Правительства."},{"type":"paragraph","number":"4","text":"На заседание могут приглашаться руководители государственных органов, специалисты и иные лица без права голоса, если они не являются членами Правительства."},{"type":"paragraph","number":"5","text":"Заседание или его часть может проводиться в закрытом режиме при рассмотрении сведений ограниченного доступа."}]},{"type":"article","number":"48","title":"Принятие решений Правительством","children":[{"type":"paragraph","number":"1","text":"Каждый член Правительства, обладающий правом голоса, имеет один голос."},{"type":"paragraph","number":"2","text":"Решение принимается большинством голосов участвующих в голосовании членов Правительства при наличии кворума."},{"type":"paragraph","number":"3","text":"При равенстве голосов предложение считается непринятым, если Премьер-министр, председательствующий на заседании, не обладает правом принять решение в форме собственного акта в пределах отдельной компетенции Премьер-министра."},{"type":"paragraph","number":"4","text":"Результаты голосования фиксируются в протоколе либо ином официальном документе."}]},{"type":"article","number":"49","title":"Постановления и распоряжения Правительства","children":[{"type":"paragraph","number":"1","text":"Правительство принимает постановления и распоряжения."},{"type":"paragraph","number":"2","text":"Постановление Правительства может иметь нормативный характер."},{"type":"paragraph","number":"3","text":"Распоряжение Правительства принимается преимущественно по индивидуальным и организационным вопросам."},{"type":"paragraph","number":"4","text":"Постановление или распоряжение не может противоречить Конституции, федеральным конституционным законам, кодексам, федеральным законам и нормативным указам Премьер-министра."},{"type":"paragraph","number":"5","text":"Нормативные постановления Правительства подлежат официальному опубликованию."},{"type":"paragraph","number":"6","text":"Неопубликованный нормативный акт Правительства, затрагивающий права, обязанности или ответственность граждан, применению не подлежит."}]},{"type":"article","number":"50","title":"Отмена и приостановление актов исполнительной власти","children":[{"type":"paragraph","number":"1","text":"Премьер-министр вправе отменить или приостановить акт Правительства, если он противоречит Конституции, федеральному законодательству или законному нормативному акту Премьер-министра."},{"type":"paragraph","number":"2","text":"Правительство вправе отменить или приостановить акт федерального министерства либо подчиненной государственной организации, если он противоречит акту большей юридической силы или принят за пределами компетенции."},{"type":"paragraph","number":"3","text":"Отмена акта должна быть мотивирована."},{"type":"paragraph","number":"4","text":"Премьер-министр и Правительство не вправе отменять судебные акты, процессуальные решения прокуратуры или Следственного комитета вне предусмотренной законом процедуры обжалования и контроля."}]},{"type":"article","number":"51","title":"Официальное опубликование актов","children":[{"type":"paragraph","number":"1","text":"Нормативные указы Премьер-министра, постановления Правительства и иные нормативные акты, затрагивающие права, обязанности, ответственность граждан или компетенцию государственных органов, подлежат размещению в установленном официальном разделе Правительства."},{"type":"paragraph","number":"2","text":"В акте может быть установлен более поздний момент вступления в силу."},{"type":"paragraph","number":"3","text":"Если иной момент не установлен, нормативный акт вступает в силу с момента официального опубликования."},{"type":"paragraph","number":"4","text":"Индивидуальный акт вступает в силу с момента доведения до сведения адресата либо с указанного в нем момента, если законом не предусмотрено иное."}]}]},{"type":"chapter","number":"VIII","title":"ВЗАИМООТНОШЕНИЯ ПРЕМЬЕР-МИНИСТРА И ПРАВИТЕЛЬСТВА С ИНЫМИ ГОСУДАРСТВЕННЫМИ ОРГАНАМИ​","children":[{"type":"article","number":"52","title":"Премьер-министр, Правительство и Парламент","children":[{"type":"paragraph","number":"1","text":"Премьер-министр и Правительство взаимодействуют с Парламентом в законодательном процессе, при рассмотрении парламентских запросов и в иных предусмотренных законом формах."},{"type":"paragraph","number":"2","text":"Правительство предоставляет Парламенту общие отчеты и сведения, необходимые для парламентского контроля, в пределах Федерального конституционного закона «О Парламенте РО»."},{"type":"paragraph","number":"3","text":"Парламент не вправе осуществлять оперативное руководство Правительством или отдельным министерством вне предусмотренных законом процедур."},{"type":"paragraph","number":"4","text":"Премьер-министр и Правительство не вправе препятствовать законной деятельности Парламента, блокировать рассмотрение законопроектов вне предусмотренной законом процедуры либо использовать исполнительные полномочия для принуждения членов Парламента к определенному голосованию."}]},{"type":"article","number":"53","title":"Премьер-министр, Правительство и судебная власть","children":[{"type":"paragraph","number":"1","text":"Премьер-министр и Правительство обязаны исполнять вступившие в силу судебные акты."},{"type":"paragraph","number":"2","text":"Премьер-министр и Правительство вправе обращаться в суд в предусмотренных законом случаях."},{"type":"paragraph","number":"3","text":"Судебный контроль за актами Премьер-министра и Правительства осуществляется в порядке, установленном судебным и процессуальным законодательством."},{"type":"paragraph","number":"4","text":"Премьер-министр и Правительство не вправе давать суду обязательное указание по разрешению конкретного дела."}]},{"type":"article","number":"54","title":"Премьер-министр, Правительство, прокуратура и Следственный комитет","children":[{"type":"paragraph","number":"1","text":"Прокуратура РО, несмотря на ее организационное нахождение в структуре Правительства РО, и Следственный комитет РО осуществляют предусмотренные законом процессуальные и надзорные полномочия самостоятельно в пределах Конституции и федерального законодательства."},{"type":"paragraph","number":"2","text":"Премьер-министр и Правительство вправе взаимодействовать с прокуратурой и Следственным комитетом по вопросам общего характера, межведомственной координации, государственной политики, материально-технического обеспечения и исполнения закона."},{"type":"paragraph","number":"3","text":"Премьер-министр и Правительство не вправе требовать заранее определенного процессуального решения по конкретному уголовному делу или проверке."},{"type":"paragraph","number":"4","text":"Законные требования прокуратуры и Следственного комитета исполняются Премьер-министром, Правительством и подчиненными им органами в пределах компетенции соответствующего органа."},{"type":"paragraph","number":"5","text":"Незаконный акт прокуратуры или Следственного комитета может быть обжалован в установленном законом порядке, но не отменяется Премьер-министром или Правительством непосредственно."}]},{"type":"article","number":"55","title":"Ответственность членов Правительства","children":[{"type":"paragraph","number":"1","text":"Члены Правительства несут уголовную, административную, дисциплинарную, гражданско-правовую и иную ответственность на общих основаниях с учетом установленных законом процессуальных гарантий."},{"type":"paragraph","number":"2","text":"Статус члена Правительства не освобождает от ответственности за злоупотребление полномочиями, коррупцию, незаконное распоряжение государственным имуществом, вмешательство в правосудие или расследование и иные правонарушения."},{"type":"paragraph","number":"3","text":"Премьер-министр вправе освободить члена Правительства от должности независимо от привлечения его к юридической ответственности."},{"type":"paragraph","number":"4","text":"Освобождение от должности не прекращает производство по делу и не аннулирует ранее совершённое правонарушение."}]}]},{"type":"chapter","number":"IX","title":"ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ​","children":[{"type":"article","number":"56","title":"Соотношение с иными нормативными актами","children":[{"type":"paragraph","number":"1","text":"Федеральные законы, указы Премьер-министра, постановления Правительства, акты министерств и внутренние акты государственных организаций применяются постольку, поскольку они не противоречат Конституции и настоящему Федеральному конституционному закону."},{"type":"paragraph","number":"2","text":"Если действующий подзаконный акт регулирует вопрос иначе, чем настоящий Федеральный конституционный закон, применяется настоящий Федеральный конституционный закон."},{"type":"paragraph","number":"3","text":"Настоящий Федеральный конституционный закон не отменяет специальные полномочия государственных органов, установленные федеральными законами, если такие полномочия не противоречат Конституции и настоящему Федеральному конституционному закону."}]},{"type":"article","number":"57","title":"Приведение актов в соответствие","children":[{"type":"paragraph","number":"1","text":"Премьер-министр и Правительство обязаны привести действующие нормативные и внутренние акты исполнительной власти в соответствие с настоящим Федеральным конституционным законом."},{"type":"paragraph","number":"2","text":"Государственные организации обязаны пересмотреть внутренние регламенты и инструкции в части, затрагивающей компетенцию Премьер-министра и Правительства."},{"type":"paragraph","number":"3","text":"Противоречащие настоящему Федеральному конституционному закону положения подзаконных актов применению не подлежат со дня вступления настоящего Федерального конституционного закона в силу."}]},{"type":"article","number":"58","title":"Вступление настоящего Федерального конституционного закона в силу","children":[{"type":"paragraph","number":"1","text":"Настоящий Федеральный конституционный закон вступает в силу с момента его официального опубликования."},{"type":"paragraph","number":"2","text":"С момента вступления настоящего Федерального конституционного закона в силу ранее принятые акты, регулирующие статус Премьер-министра и Правительства, применяются постольку, поскольку они не противоречат настоящему Федеральному конституционному закону. Нормативно-правовой акт подписан Премьер-министром РО 06.09.2026 Марк Брагин ​"}]}]}]};
